	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setForceSync(true);
	}

	private static long countSetDirectories(Path directory) throws IOException {
		try (Stream<Path> entries = Files.list(directory)) {
			return entries.filter(path -> path.getFileName().toString().startsWith("set")).count();
		}
	}

	private static final class FailingPersistentSetFactory extends PersistentSetFactory<Long> {
		private final int failedSet;
		private final IOException failure;
		private final AtomicInteger createCalls = new AtomicInteger();
		private final AtomicBoolean closed = new AtomicBoolean();

		private FailingPersistentSetFactory(File dataDir, int failedSet, IOException failure) throws IOException {
			super(dataDir);
			this.failedSet = failedSet;
			this.failure = failure;
		}

		@Override
		PersistentSet<Long> createSet(String name, Function<Long, byte[]> writeFunc,
				Function<ByteBuffer, Long> readFunc) throws IOException {
			PersistentSet<Long> set = super.createSet(name, writeFunc, readFunc);
			if (createCalls.incrementAndGet() == failedSet) {
				throw failure;
			}
			return set;
		}

		@Override
		public synchronized void close() throws IOException {
			closed.set(true);
			super.close();
		}
	}
